import sys

def is_maximal(n, s):
    if n == 1:
        # only one seat. Seating is '1' -> maximal (no more people).
        # If '0', not maximal.
        return s[0] == '1'
    # Check adjacent 1s
    for i in range(n - 1):
        if s[i] == '1' and s[i + 1] == '1':
            return False
    # Check each 0 has at least one neighbor that is 1
    for i in range(n):
        if s[i] == '0':
            left_ok = i > 0 and s[i - 1] == '1'
            right_ok = i < n - 1 and s[i + 1] == '1'
            if not left_ok and not right_ok:
                return False
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""
    if n != len(s):
        print("No")
        return
    if is_maximal(n, s):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
"}

