# Read the number of commands
n = int(input())

# Initialize current directory as root (empty stack)
current_dir = []

for _ in range(n):
    line = input().strip()
    if line == 'pwd':
        # Print absolute path starting with / and ending with /
        print('/' + '/'.join(current_dir) + '/')
    else:
        # cd command, extract the path
        parts = line.split()
        path = parts[1]

        # Split path by /
        components = path.split('/')

        # Process each component
        for comp in components:
            if comp == '..':
                # Go up one level
                if current_dir:
                    current_dir.pop()
            else:
                # Add the directory
                current_dir.append(comp)
"}

