import sys

def get_kth_perfect_number(k):
    if k <= 9:
        # Two-digit numbers: tens = k, units = 10 - k
        return 10 * k + (10 - k)
    else:
        # Three-digit numbers: hundreds = k // 10, tens = k % 10, units = 9 - (k % 10)
        hundreds = k // 10
        tens = k % 10
        units = 9 - (k % 10)
        return hundreds * 100 + tens * 10 + units

if __name__ == "__main__":
    k = int(sys.stdin.readline())
    print(get_kth_perfect_number(k))
"}

