def is_valid(s):
    """Check if the string consists of alternating blocks of H's and Q's.
    Q blocks must have at least 2 Q's, H blocks must have at least 1 H."""
    i = 0

    # First, check if we just have H blocks
    if all(s[i:i+1] == 'H' for i in range(0, len(s))):
        return True

    # Check if we just have Q blocks
    if all(s[i:i+1] == 'Q' for i in range(0, len(s))):
        return False  # Q blocks need at least 2 Q's

    # Now check alternating blocks of H and Q
    # The pattern could be H block -> Q block -> H block -> Q block -> ...
    # or Q block -> H block -> Q block -> H block -> ...

    # Try both possibilities
    for first_block in ['H', 'Q']:
        i = 0
        valid = True

        # Get the first block
        j = i
        while j < len(s) and s[j] == first_block:
            j += 1

        if first_block == 'H':
            # H block must have at least 1 H
            if j - i < 1:
                valid = False
        else:
            # Q block must have at least 2 Q's
            if j - i < 2:
                valid = False

        if not valid:
            continue

        i = j

        # Check alternating blocks
        while i < len(s):
            # Switch block type
            if first_block == 'H':
                if s[i] != 'Q':
                    valid = False
                    break
                first_block = 'Q'
            else:
                if s[i] != 'H':
                    valid = False
                    break
                first_block = 'H'

            # Get block size
            j = i
            while j < len(s) and s[j] == first_block:
                j += 1

            if first_block == 'H':
                # H block must have at least 1 H
                if j - i < 1:
                    valid = False
                    break
            else:
                # Q block must have at least 2 Q's
                if j - i < 2:
                    valid = False
                    break

            i = j

        if valid:
            return True

    return False

s = sys.stdin.readline().strip()
print("Yes" if is_valid(s) else "No")
