def solve():
    n = input().strip()
    digits = list(n)
    freq = {}
    for ch in n:
        digit = int(ch)
        freq[digit] = freq.get(digit, 0) + 1

    # Build the two numbers
    num1 = []
    num2 = []

    # First, handle digits that can pair to make 10
    for d in range(1, 10):
        if freq.get(d, 0) > 0:
            pair_d = 10 - d
            if freq.get(pair_d, 0) > 0:
                if d != pair_d:
                    num1.append(str(d))
                    num2.append(str(pair_d))
                    freq[d] -= 1
                    freq[pair_d] -= 1
                else:
                    num1.append(str(d))
                    num2.append(str(d))
                    freq[d] -= 2
            else:
                num1.append(str(d))
                num2.append(str(d))

    # Now handle the remaining digits (including leading zeros)
    # For maximum trailing zeroes, we want the last digits to sum to 10
    # We'll start from the rightmost digit
    for i in range(len(n)-1, -1, -1):
        digit = int(n[i])

        # If this digit is already used, skip
        if freq.get(digit, 0) > 0:
            pair_d = 10 - digit

            # Check if the pair exists in the frequency map
            if freq.get(pair_d, 0) > 0:
                if digit != pair_d:
                    # Different digits
                    num1.append(str(digit))
                    num2.append(str(pair_d))
                    freq[digit] -= 1
                    freq[pair_d] -= 1
                else:
                    # Same digit, need two of them
                    if freq[digit] >= 2:
                        num1.append(str(digit))
                        num2.append(str(digit))
                        freq[digit] -= 2
            else:
                # Just add this digit to both numbers
                num1.append(str(digit))
                num2.append(str(digit))

    # Ensure we have exactly two numbers
    if len(num1) != len(n) or len(num2) != len(n):
        while len(num1) < len(n):
            num1.append('0')
            num2.append('0')

    print(''.join(num1))
    print(''.join(num2))

