def min_bulbo_cost(n, x, intervals):
    # dp[pos] = minimum total cost to be at position pos before this turn
    # We'll use a dictionary for efficiency

    # Initialize with position x
    dp = {x: 0}

    for lstart, lend in intervals:
        new_dp = {}

        # For each possible previous position, consider moving to all possible positions
        for prev_pos, prev_cost in dp.items():
            # Cost to move from prev_pos to new_pos
            move_cost = abs(new_pos - prev_pos)

            # Cost to nearest bulb at this turn
            bulb_cost = 0 if lstart <= new_pos <= lend else (lstart - new_pos if new_pos < lstart else new_pos - lend)

            # Consider all positions from max(lstart-5, 1) to min(lend+5, 10**9)
            # This covers all possible optimal positions

            for new_pos in range(max(lstart - 5, 1), min(lend + 5, 10**9) + 1):
                total_cost = prev_cost + move_cost + bulb_cost

                if new_pos not in new_dp or total_cost < new_dp[new_pos]:
                    new_dp[new_pos] = total_cost

        dp = new_dp

    return min(dp.values())

# Read input
n, x = map(int, input().split())
intervals = []
for _ in range(n):
    lstart, lend = map(int, input().split())
    intervals.append((lstart, lend))

result = min_bulbo_cost(n, x, intervals)
print(result)
