    # Find the position i such that the bar is t% filled
    # i-1 full sections and some value a in position i
    i = 1
    for j in range(1, n + 1):
        if j > 1:
            # Try placing the varying value at position j
            for a in range(0, k + 1):
                sat = k * (j - 1) + a
                percent = (sat / (k * n)) * 100
                if abs(percent - t) < 1e-9:
                    i = j
                    break
            else:
                continue
        else:
            # Position 1 can't have any value, it must be k
            continue

    # Create the result array
    result = [k] * (i - 1)
    if i <= n:
        result.append(k)  # Position i should be k, not any value 0..k
    result.extend([0] * (n - i))

    return result

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    t = int(data[2])

    result = solve(n, k, t)
    sys.stdout.write(' '.join(map(str, result)))

token = 0
