import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    rows = []
    for _ in range(n):
        row = list(map(int, [next(it) for _ in range(m)]))
        rows.append(row)

    # Check if identity permutation already satisfies
    # Actually we must check if all rows are sorted
    # No swaps needed
    # But also we might swap columns and then swap within rows
    # So first check identity column order
    ok = True
    for row in rows:
        for i in range(m):
            if row[i] != i + 1:
                ok = False
                break
        if not ok:
            break
    if ok:
        print("YES")
        return

    # Try all column swaps
    for i in range(m):
        for j in range(i + 1, m):
            # Apply swap i <-> j to all rows
            new_rows = []
            for row in rows:
                new_row = row.copy()
                new_row[i], new_row[j] = new_row[j], new_row[i]
                new_rows.append(new_row)

            # Now check if we can fix each row with at most one swap
            all_good = True
            for row in new_rows:
                # Already sorted
                ok = True
                for idx in range(m):
                    if row[idx] != idx + 1:
                        ok = False
                        break
                if ok:
                    continue

                # Find differences
                diffs = []
                for idx in range(m):
                    if row[idx] != idx + 1:
                        diffs.append(idx)
                if len(diffs) != 2:
                    all_good = False
                    break
                idx1, idx2 = diffs
                # Swap those two and check
                row[idx1], row[idx2] = row[idx2], row[idx1]
                ok = True
                for idx in range(m):
                    if row[idx] != idx + 1:
                        ok = False
                        break
                if ok:
                    continue
                else:
                    all_good = False
                    break

            if all_good:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    solve()
