import sys

def solve():
    n = int(sys.stdin.readline())
    strings = [sys.stdin.readline().strip() for _ in range(n)]

    # Dictionary to count total weight for each letter
    letter_weights = {}
    # Set of letters that appear as first character
    first_letters = set()

    for s in strings:
        for i, ch in enumerate(s):
            weight = 10 ** i
            if ch not in letter_weights:
                letter_weights[ch] = 0
            letter_weights[ch] += weight

            if i == 0:
                first_letters.add(ch)

    # Sort letters by total weight descending
    sorted_letters = sorted(letter_weights.keys(), key=lambda x: letter_weights[x], reverse=True)

    # Assign digits: first to first letters
    assigned = {}
    available_digits = list(range(10))

    # First, assign digits to first letters (cannot be 0)
    for letter in sorted_letters:
        if letter in first_letters:
            # Assign smallest available digit > 0
            digit = available_digits[0] if available_digits[0] > 0 else available_digits[1]
            assigned[letter] = digit
            available_digits.remove(digit)

    # Then assign digits to remaining letters
    for letter in sorted_letters:
        if letter not in assigned:
            # Assign smallest available digit
            assigned[letter] = available_digits[0]
            available_digits.remove(assigned[letter])

    # Calculate sum
    total = 0
    for s in strings:
        num = 0
        for i, ch in enumerate(s):
            num = num * 10 + assigned[ch]
        total += num

    print(total)

if __name__ == "__main__":
    solve()
"}

