        for i in range(n):
            for j in range(m):
                grid[i] = grid[i][:j] + str(int(grid[i][j])) + grid[i][j+1:]

        # Store grid as list of strings
        grid = [row for row in grid if row]

        # We'll track operations
        operations = []

        # For each row from top to bottom
        for i in range(n):
            # For each column from left to right
            for j in range(m):
                # If cell (i, j) is 1, we need to flip it
                if grid[i][j] == '1':
                    # If not on the bottom row, flip three cells
                    if i < n - 1:
                        # Flip (i, j), (i, j+1), (i+1, j)
                        operations.append((i+1, j+1, i+1, j+2, i+2, j+1))
                    else:
