import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    l = int(next(it))
    v1 = int(next(it))
    v2 = int(next(it))

    a = [int(next(it)) for _ in range(n)]

    # For top half (0 ≤ a_i < l): Anton picks it up with probability 1
    # For bottom half (l ≤ a_i < 2l): Anton picks it up with probability (l - a_i) / l
    probs = []
    for ai in a:
        if ai < l:
            p = 1.0
        else:
            p = (l - ai) / l
        probs.append(p)

    # DP
    dp = [0.0] * (n + 1)
    dp[0] = 1.0

    for p in probs:
        new_dp = [0.0] * (n + 1)
        for j in range(n + 1):
            new_dp[j] = dp[j] * (1.0 - p)
            if j > 0:
                new_dp[j] += dp[j - 1] * p
        dp = new_dp

    for i in range(n + 1):
        print(f"{dp[i]:.20f}")

if __name__ == "__main__":
    solve()
