import sys
import math

def min_time_to_station(d, a, v):
    """Calculate minimum time to reach station with acceleration a and max speed v"""
    if v <= 0:
        return float('inf')

    t_max = v / a  # Time to reach max speed
    d1 = 0.5 * a * t_max * t_max  # Distance covered while accelerating

    if d1 >= d:
        # Doesn't reach max speed
        return math.sqrt(2 * d / a)
    else:
        # Reaches max speed
        return t_max + (d - d1) / v

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
