    a = int(data[1])
    d = int(data[2])

    # Remaining data contains ti and vi pairs
    idx = 3
    for i in range(n):
        ti = int(data[idx])
        vi = int(data[idx + 1])
        idx += 2

        # Calculate minimum arrival time
        own_time = min_time_to_station(d, a, vi)
        arrival_time = max(ti + own_time, arrival_time)

        print(f"{arrival_time:.10f}")

if __name__ == "__main__":
    solve()
