    next_pos = {c: [None] * n for c in ['A', 'T', 'G', 'C']}

    # Build next arrays
    for c in ['A', 'T', 'G', 'C']:
        next_pos[c][n - 1] = n
        for i in range(n - 2, -1, -1):
            if s[i + 1] == c:
                next_pos[c][i] = i + 1
            else:
                next_pos[c][i] = i + 1

    # Process queries
    out_lines = []
    for _ in range(q):
        event = next(it).decode('utf-8')
        if event == '1':
            x = int(next(it)) - 1
            new_char = next(it).decode('utf-8')

            # Update character at position x
            s = s[:x] + new_char + s[x+1:]

            # Update next arrays
