def solve():
    n = int(input())
    strings = [input().strip() for _ in range(n)]

    # Count frequency of each letter
    freq = {chr(ord('a') + i): 0 for i in range(10)}

    # Track letters that appear as first character of any string
    first_chars = set()

    for s in strings:
        for i, ch in enumerate(s):
            freq[ch] += 1
            if i == 0:
                first_chars.add(ch)

    # Sort letters by frequency (descending) and then by alphabetical order
    sorted_letters = sorted(freq.keys(), key=lambda x: (-freq[x], x))

    # Assign digits to letters
    digit_map = {}
    remaining_digits = set(range(10))

    # First handle first characters (can't be 0)
    for ch in sorted_letters:
        if ch in first_chars:
            # Can't assign 0, assign smallest remaining digit
            digit = min(remaining_digits - {0})
            digit_map[ch] = digit
            remaining_digits.remove(digit)
        else:
            # Can assign 0, assign smallest remaining digit
            digit = min(remaining_digits)
            digit_map[ch] = digit
            remaining_digits.remove(digit)

    # Calculate the sum
    total = 0
    for s in strings:
        num = 0
        for ch in s:
            num = num * 10 + digit_map[ch]
        total += num

    print(total)

