import sys
sys.setrecursionlimit(100000)

def solve():
    n, m = map(int, sys.stdin.readline().split())
    graph = [[] for _ in range(n + 1)]

    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    separate_count = 0

    # Find connected components and count nodes
    for start in range(1, n + 1):
        if not visited[start]:
            queue = [start]
            visited[start] = True
            component_nodes = 1

            while queue:
                u = queue.pop(0)
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
                        component_nodes += 1

            # Count edges in this component
            component_edges = 0
            # Only count each edge once
            for u in range(1, n + 1):
                if visited[u]:
                    for v in graph[u]:
                        if u < v:  # Only count each edge once
                            component_edges += 1

            # Check if this component has a cycle
            if component_edges < component_nodes:
                # Tree, at least one separate node
                separate_count += 1
            else:
                # Has at least one cycle, can avoid separate nodes
                pass

    print(separate_count)

solve()
