            len_t = len(t)

            # DP table for edit distance between t and u
            dp = [[0] * (len_u + 1) for _ in range(len_t + 1)]

            # Initialize DP table
            for i in range(len_t + 1):
                dp[i][0] = i  # delete all from t
            for j in range(len_u + 1):
                dp[0][j] = j  # insert all into t

            # Fill DP table
