def is_in_check(board, black_king_pos, rook1_pos, rook2_pos, white_king_pos):

    # Check if rook is in same row
    for rook_pos in [rook1_pos, rook2_pos]:
        if board[rook_pos[0]][rook_pos[1]] == 1 and black_king_pos[0] == rook_pos[0]:
            # Same row, check if path is clear
            start, end = sorted([black_king_pos[1], rook_pos[1]])
            for y in range(start + 1, end):
                if board[black_king_pos[0]][y] != 0:
                    break
            else:
                return True

    # Check if rook is in same column
    for rook_pos in [rook1_pos, rook2_pos]:
        if board[rook_pos[0]][rook_pos[1]] == 1 and black_king_pos[1] == rook_pos[1]:
            # Same column, check if path is clear
            start, end = sorted([black_king_pos[0], rook_pos[0]])
            for x in range(start + 1, end):
                if board[x][black_king_pos[1]] != 0:
                    break
            else:
                return True

    # Check if white king is adjacent
    if abs(black_king_pos[0] - white_king_pos[0]) <= 1 and abs(black_king_pos[1] - white_king_pos[1]) <= 1:
        return True

    return False

def is_safe_position(board, black_king_pos, rook1_pos, rook2_pos, white_king_pos):
    # Check if black king can move to this position
    # 1. Position must be within bounds
    if not (0 <= black_king_pos[0] < 8 and 0 <= black_king_pos[1] < 8):
        return False

    # 2. Position must not be occupied by any piece
    if board[black_king_pos[0]][black_king_pos[1]] != 0:
        return False

    # 3. Position must not be adjacent to white king
    if abs(black_king_pos[0] - white_king_pos[0]) <= 1 and abs(black_king_pos[1] - white_king_pos[1]) <= 1:
        return False

    # 4. Position must not be in check
    if is_in_check(board, black_king_pos, rook1_pos, rook2_pos, white_king_pos):
        return False

    return True

def solve():
    positions = input().strip().split()
    if len(positions) != 4:
        return

    # Convert positions to (col, row) where col is 0-7 and row is 0-7
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (col, row)

    # The 4 positions: rook1, rook2, white_king, black_king
    pos1 = parse_pos(positions[0])
    pos2 = parse_pos(positions[1])
    w_king = parse_pos(positions[2])
    b_king = parse_pos(positions[3])

    # Create board
    board = [[0 for _ in range(8)] for _ in range(8)]
    board[pos1[0]][pos1[1]] = 2  # White rook
    board[pos2[0]][pos2[1]] = 2
    board[w_king[0]][w_king[1]] = 1  # White king
    board[b_king[0]][b_king[1]] = -1  # Black king

    # Check if black king is in check
    if is_in_check(board, b_king, pos1, pos2, w_king):
        # Check if there are any safe positions
        has_safe = False
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
