            return 0

        # If we're at x = 1, cost is 0
        if x == 1:
            return 0

        # If we can't divide (x < k), just subtract all the way
        if x < k:
            return A * (x - 1)

        # Option 1: Subtract all the way
        cost_subtract = A * (x - 1)

