import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Initialize result array
    result = [0] * n

    # Find the nearest zero from the left
    last_zero = -1
    for i in range(n):
        if arr[i] == 0:
            last_zero = i
        # If we've seen a zero, update distance
        if last_zero != -1:
            result[i] = i - last_zero
        # else: result[i] remains 0

    # Find the nearest zero from the right and update
    last_zero = -1
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero = i
        # If we've seen a zero, update distance
        if last_zero != -1:
            result[i] = min(result[i], last_zero - i)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

