    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Initialize result array
    result = [0] * n

    # Find the nearest zero from the left
    last_zero = -1
    for i in range(n):
        if arr[i] == 0:
            last_zero = i
        if last_zero != -1:
            # Distance to nearest zero on the left
            result[i] = i - last_zero

    # Find the nearest zero from the right
    last_zero = -1
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero = i
        if last_zero != -1:
            # Distance to nearest zero on the right
            result[i] = min(result[i], last_zero - i)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()

