def longest_non_decreasing_sequence(n, T, a):

    # If the array is non-decreasing, the answer is n * T
    if all(a[i] <= a[i + 1] for i in range(n - 1)):
        return n * T

    # Count how many times each value appears
    value_count = {}
    for value in a:
        if value in value_count:
            value_count[value] += 1
        else:
            value_count[value] = 1

    # Find max value
    max_val = max(a)

    # If we can get all values from 1 to max_val, we can get max_val + (T - 1)
    if all(value in value_count for value in range(1, max_val + 1)):
        # But we need to consider if we can actually extend this sequence
        # If the array contains all values from 1 to max_val, we can at least get max_val
        # And we can also get an extra element from each subsequent repetition
        return max_val + (T - 1)

    # Otherwise, we can just get max_val + (T - 1) * 1
    return max_val + (T - 1)

# Read input
