import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    swaps = sys.stdin.readline().strip()

    # DSU to find connected components of positions with allowed swaps
    parent = list(range(n + 1))  # 1-indexed

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            parent[py] = px

    for i in range(n - 1):
        if swaps[i] == '1':
            union(i + 1, i + 2)

    # Group elements by connected component
    comp_elements = {}
    for i in range(1, n + 1):
        comp = find(i)
        if comp not in comp_elements:
            comp_elements[comp] = []
        comp_elements[comp].append(a[i - 1])

    # Determine which elements should be in each block
    comp_correct = {}
    for i in range(1, n + 1):
        comp = find(i)
        if comp not in comp_correct:
            comp_correct[comp] = []
        comp_correct[comp].append(i)

    # Check if we can assign elements correctly
    for comp in comp_correct:
        if sorted(comp_elements[comp]) != sorted(comp_correct[comp]):
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
