def can_fix_row(row):
    """Check if a row can be made sorted with one swap"""
    if row == list(range(1, len(row) + 1)):
        return True

    # Try all possible swaps
    for i in range(len(row)):
        for j in range(i + 1, len(row)):
            swapped = row[:]
            swapped[i], swapped[j] = swapped[j], swapped[i]
            if swapped == list(range(1, len(row) + 1)):
                return True

    return False


def solve():
    n, m = map(int, input().split())
    table = []
    for _ in range(n):
        table.append(list(map(int, input().split())))

    # Try all possible column swaps (including no swap)
    for col_swap in range(m + 1):
        # col_swap: 0 means no swap
        # col_swap: 1 means swap column 0 with column 1
        # col_swap: 2 means swap column 0 with column 2
        # etc.
        if col_swap > m:
            break

        # We need to try all possible pairs of columns
        # col_swap = (i, j) where i < j
        for i in range(m):
            for j in range(i + 1, m):
                # Swap columns i and j in each row
                new_table = []
                for row in table:
                    new_row = row[:]
                    new_row[i], new_row[j] = new_row[j], new_row[i]
                    new_table.append(new_row)

                # Check if all rows can be fixed with at most one swap
                all_fixed = True
                for row in new_table:
                    if not can_fix_row(row):
                        all_fixed = False
                        break

                if all_fixed:
                    print("YES")
                    return

    print("NO")

solve()
