import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    steps = 0

    while True:
        # Find who gets killed in this step
        killed = set()
        for i in range(len(arr) - 1):
            if arr[i] > arr[i + 1] and i + 1 not in killed:
                killed.add(i + 1)

        # If no one was killed, we're done
        if not killed:
            break

        # Remove killed people
        for i in reversed(range(len(arr))):
            if i in killed:
                del arr[i]

        steps += 1

    print(steps)

if __name__ == "__main__":
    solve()
