from collections import deque
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, m = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))

    received = [0] * n
    queue = deque(range(1, n + 1))
    order = []

    while queue:
        child = queue.popleft()
        received[child - 1] += m

        if received[child - 1] >= a[child - 1]:
            order.append(child)
        else:
            queue.append(child)

    print(order[-1])

if __name__ == "__main__":
    solve()
