import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    dist = [0] * n
    last_zero = -n  # far left
    for i in range(n):
        if a[i] == 0:
            last_zero = i
        else:
            dist[i] = i - last_zero
    # right pass
    last_zero = n + n  # far right
    for i in range(n-1, -1, -1):
        if a[i] == 0:
            last_zero = i
        else:
            dist[i] = min(dist[i], last_zero - i)
    print(' '.join(map(str, dist)))

