import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    p = list(map(int, it))
    s = next(it)

    # compute prefix differences
    # preA[k] = sum of p_i for i=0..k-1 (0-indexed) that are 'A'
    # preB[k] = sum of p_i for i=0..k-1 that are 'B'
    # pref[k] = preA[k] - preB[k]
    pref = [0] * (n + 1)
    for k in range(1, n + 1):
        if s[k - 1] == 'A':
            pref[k] = pref[k - 1] + p[k - 1]
        else:
            pref[k] = pref[k - 1] - p[k - 1]

    # compute suffix differences
    suf = [0] * (n + 1)
    for k in range(1, n + 1):
        if s[n - k] == 'A':
            suf[k] = suf[k - 1] + p[n - k]
        else:
            suf[k] = suf[k - 1] - p[n - k]

    max_pref = max(pref)
    max_suf = max(suf)

    # initial Bob strength
    bob = 0
    for i in range(n):
        if s[i] == 'B':
            bob += p[i]

    max_diff = max(0, max_pref, max_suf)
    print(bob + max_diff)

if __name__ == "__main__":
    solve()
