for _ in range(n):
    a, b = map(int, input().split())
    cards.append((a, b))

    # Count current front colors
    if a in front_counts:
        front_counts[a] += 1
    else:
        front_counts[a] = 1

    # Count back colors
    if b in back_counts:
        back_counts[b] += 1
    else:
        back_counts[b] = 1

# Check if any color already has at least half the cards
half = (n + 1) // 2
for color, count in front_counts.items():
    if count >= half:
        print(0)
        exit()

# Try to find the best color to target
min_flips = float('inf')

for color in set(front_counts.keys()).union(set(back_counts.keys())):
    count_front = front_counts.get(color, 0)
    count_back = back_counts.get(color, 0)

    # How many cards can we get to show this color?
    max_possible = count_front + count_back

    # If we can't get enough cards, skip
    if max_possible < half:
        continue

    # How many more do we need?
    needed = max(0, half - count_front)

    # If we need more than we have, we can't achieve it
    if needed > count_back:
        continue

    # Minimum flips needed to get 'needed' cards
    min_flips = min(min_flips, needed)

if min_flips != float('inf'):
    print(min_flips)
else:
    print(-1)
