import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    radii = list(map(int, data[1:1+n]))

    # Sort radii
    radii.sort()

    # Count frequency of each radius
    freq = {}
    for r in radii:
        freq[r] = freq.get(r, 0) + 1

    # List to store snowman configurations
    snowmen = []

    # Try to form snowmen greedily
    while True:
        # Find the current largest available radius
        r1 = None
        for r in reversed(radii):
            if freq[r] > 0:
                r1 = r
                break

        if r1 is None:
            break

        # Find the second largest available radius that's different from r1
        r2 = None
        for r in reversed(range(1, r1)):
            if freq[r] > 0:
                r2 = r
                break

        if r2 is None:
            break

        # Find the third largest available radius that's different from both
        r3 = None
        for r in reversed(range(1, r2)):
            if freq[r] > 0:
                r3 = r
                break

        if r3 is None:
            break

        # Record this snowman
        snowmen.append((r1, r2, r3))

        # Decrease counts
        freq[r1] -= 1
        freq[r2] -= 1
        freq[r3] -= 1

    # Output results
    print(len(snowmen))
    for snowman in snowmen:
        print(f"{snowman[0]} {snowman[1]} {snowman[2]}")

if __name__ == "__main__":
    solve()
"}

