    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    swaps = data[n+1]

    sorted_a = list(range(1, n+1))

    for i in range(n-1):
        # Check if we can swap at position i (1-indexed i+1)
        if swaps[i] == '1':
            continue

        # We can't swap at position i, check conditions
        # If a[i] > a[i+1], then in sorted array a[i] must be i+1 and a[i+1] must be i+2
        if a[i] > a[i+1]:
            # In sorted array, if we can't swap at position i, then a[i] should be i+1 and a[i+1] should be i+2
            if a[i] != i+1 or a[i+1] != i+2:
                print("NO")
                return

    print("YES")

if __name__ == "__main__":
    solve()

