    """Check if the king is currently in check"""
    # Check if any rook can attack the king
    for rook_x, rook_y in board['rooks']:
        if rook_x == king_x:  # same column
            # Check if there are any pieces between them
            # The rook is adjacent if there are no pieces between
            # and the distance is 1
            if abs(king_y - rook_y) == 1:
                return True
        elif rook_y == king_y:  # same row
            if abs(king_x - rook_x) == 1:
                return True

    # Check if white king can attack
    white_king_x, white_king_y = board['white_king']
    if abs(king_x - white_king_x) <= 1 and abs(king_y - white_king_y) <= 1:
        return True

    return False

def is_valid_position(king_x, king_y, board):
    """Check if the king can be at this position (not in check)
    and also not adjacent to white king if in check"""
    if is_in_check(king_x, king_y, board):
        # If in check, cannot stay in place
        return False
    return True

