    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    s = int(next(it))
    f = int(next(it))

    max_participants = -1
    best_time = 1

    for t in range(1, n + 1):
        participants = 0

        for i in range(n):
            # Time in zone i+1
            zone_start = (t + i) % n
            if zone_start == 0:
                zone_start = n

            zone_end = (t + i + 1) % n
            if zone_end == 0:
                zone_end = n

            # Contest runs from t to t+1
            # In zone i+1, contest runs from (t+i) to (t+i+1) modulo n
            # Determine if contest covers hours >= s and <= f

            # Start time
            contest_start = (t + i) % n
            contest_end = (t + i + 1) % n

            # If start == 0, it's actually hour n (0 hour, but use n)
            if contest_start == 0:
                contest_start = n
            if contest_end == 0:
                contest_end = n

            # Contest runs from contest_start to contest_end
            # Find intersection with [s, f]

            if contest_start < contest_end:
                # Contest doesn't wrap around
                if contest_start >= s and contest_end <= f:
                    participants += a[i]
            else:
                # Contest wraps around
                if contest_start >= s:
                    participants += a[i]
                if contest_end <= f:
                    participants += a[i]

        if participants > max_participants:
