def compute_scores(n, times, vasya_idx=0, petya_idx=1):
    """Compute scores for Vasya and Petya given times matrix"""
    scores = [0.0] * n
    for i in range(n):
        score = 0.0
        for j in range(5):
            m = times[i][j]
            if m == -1:
                # Problem not solved, score is 0
                pass
            else:
                # Problem solved, score = x * (1 - m / 250)
                # x = 1500 * (number of solvers) / n
                # We need to determine number of solvers
                solvers = 0
                for k in range(n):
                    if times[k][j] != -1:
                        solvers += 1
                x = 1500 * solvers / n
                score += x * (1 - m / 250)
        scores[i] = score
    return scores[vasya_idx], scores[petya_idx]

