    n, m = map(int, input().split())
    c = list(map(int, input().split()))

    # Count how many children of each color
    color_count = [0] * (m + 1)
    for color in c:
        color_count[color] += 1

    # Count left and right mittens for each color
    # (each color has exactly the number of children with that color)
    mitten_count = [0] * (m + 1)
    for i in range(1, m + 1):
        mitten_count[i] = color_count[i]

    # We'll store for each color: (left mittens, right mittens, children with this color)
    color_info = []
    for i in range(1, m + 1):
        color_info.append((mitten_count[i], mitten_count[i], color_count[i]))

    # For each child, try to give same-color mittens if possible
    result = []

    for child in range(n):
        color = c[child]
        # Try to give same-color mittens
        if color_info[color][0] > 0 and color_info[color][1] > 0:
            result.append((color, color))
            color_info[color] = (color_info[color][0] - 1, color_info[color][1] - 1, color_info[color][2])
        else:
            # Need to give different colors
            for left_color in range(1, m + 1):
                if left_color == color:
                    continue
                if color_info[left_color][0] > 0:
                    for right_color in range(1, m + 1):
