        if p[right] <= m:
            less_count += 1
        else:
            greater_count += 1

        # Check if we can extend left while maintaining balance
        for left in range(0, right + 1):
            if p[left] <= m:
                less_count -= 1
            else:
                greater_count -= 1

            # Check if m is the median
            # Condition: (number of elements <= m) - 1 == (number of elements > m)
