import sys

# Parse input
def parse_position(pos):
    return ord(pos[0]) - ord('a'), int(pos[1]) - 1

# Check if a square is in check
def is_in_check(x, y, rook1, rook2, white_king, black_king):
    # Check if black king is at (x, y)
    if black_king == (x, y):
        # Check if white king can capture black king
        if abs(white_king[0] - x) <= 1 and abs(white_king[1] - y) <= 1:
            return True

        # Check if either rook can capture black king
        if rook1[0] == x:
            # Same column, check path
            min_r, max_r = sorted([rook1[1], rook2[1]])
            if min_r <= y <= max_r:
                return True
        elif rook1[1] == y:
            # Same row, check path
            min_c, max_c = sorted([rook1[0], rook2[0]])
            if min_c <= x <= max_c:
                return True
        elif rook2[0] == x:
            min_r, max_r = sorted([rook2[1], rook1[1]])
            if min_r <= y <= max_r:
                return True
        elif rook2[1] == y:
            min_c, max_c = sorted([rook2[0], rook1[0]])
            if min_c <= x <= max_c:
                return True

    return False

# Check if black king can move to (x, y)
def can_move_to(x, y, rook1, rook2, white_king, black_king):
    # Check if square is within bounds
    if 0 <= x < 8 and 0 <= y < 8:
        # Check if square is not occupied
        if (x, y) == black_king:
            return False
        if (x, y) == white_king:
            return False
        if (x, y) == rook1:
            return False
        if (x, y) == rook2:
            return False

        # Check if square is not in check
        if not is_in_check(x, y, rook1, rook2, white_king, black_king):
            return True

    return False

# Main
if __name__ == "__main__":
    positions = sys.stdin.read().strip().split()

    # Parse positions
    if len(positions) != 4:
        sys.exit(1)

    rook1 = parse_position(positions[0])
    rook2 = parse_position(positions[1])
    white_king = parse_position(positions[2])
    black_king = parse_position(positions[3])

    # Check if black king is in check
    if not is_in_check(black_king[0], black_king[1], rook1, rook2, white_king, black_king):
        print("OTHER")
        sys.exit(0)

    # Check all adjacent squares
    directions = [(-1, -1), (-1, 0), (-1, 1),
