n = int(input())
cards = []
front_freq = {}

for _ in range(n):
    front, back = map(int, input().split())
    cards.append((front, back))

    # Count front colors
    if front in front_freq:
        front_freq[front] += 1
    else:
        front_freq[front] = 1

required = (n + 1) // 2  # ceil(n/2)

# Check if already funny
for color, count in front_freq.items():
    if count >= required:
        print(0)
        exit()

# Try to find minimum flips
min_flips = float('inf')

for target_color, _ in front_freq.items():
    # How many flips do we need to get target_color?
    flips_needed = required - front_freq[target_color]

    # For each card, decide if we need to flip it
    total_flips = 0

    for i in range(n):
        front, back = cards[i]

        if front == target_color:
            # Already shows target_color, no flip needed
            continue
        elif back == target_color:
            # Flip to get target_color
            total_flips += 1
        else:
            # Neither side is target_color
            continue

    if total_flips <= flips_needed:
        min_flips = min(min_flips, total_flips)

if min_flips != float('inf'):
    print(min_flips)
else:
    print(-1)
"}

