    # All years between prev+1 and year-1 have the same population
    if prev < year - 1:
        for y in range(prev + 1, year):
            if current_population > max_population:
                max_population = current_population
                result_year = y
            elif current_population == max_population and y < result_year:
                result_year = y
    prev = year

print(result_year, max_population)
